contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to deposit; require this test contract has enough balance
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record balances before
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform deposit on c sending 'amount' wei
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // balances after deposit
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // attempt to withdrawAll as this contract
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // Single assert: if withdrawAll did not revert then c lost exactly 'amount' and this gained exactly 'amount';
        // if it reverted then balances equal those after deposit.
        assert((!reverted && afterC + amount == afterDepositC && afterThis == afterDepositThis + amount) || (reverted && afterC == afterDepositC && afterThis == afterDepositThis));
    }

    receive() external payable { }
}

